SELECT c."customerName", e."firstName", e."lastName"
FROM customers c JOIN employees e ON c."salesRepEmployeeNumber" = e."employeeNumber"
WHERE "jobTitle" = 'Sales Rep';

SELECT country, COUNT("customerNumber") AS total
FROM customers c
GROUP BY country;

SELECT c."customerName", pay."paymentDate", pay.amount
FROM payments pay JOIN customers c ON pay."customerNumber" = c."customerNumber"
GROUP BY "customerNumber";

SELECT status, COUNT("orderNumber") AS total
FROM orders o
GROUP BY status;

SELECT *
FROM products p
GROUP BY "productLine";

SELECT e."firstName", e."lastName", of.city
FROM employees e JOIN offices of ON e."officeCode" = of."officeCode"
GROUP BY "officeCode";

SELECT "productLine", AVG("buyPrice") AS avg_buy_price
FROM products p
GROUP BY "productLine";

SELECT c.*, o.*
FROM customers c JOIN orders o ON c."customerNumber" = o."customerNumber"
GROUP BY "customerNumber";

SELECT "productLine", MAX("MSRP") AS max_msrp
FROM products p
GROUP BY "productLine";

SELECT "productVendor", MIN("buyPrice") AS min_buy_price
FROM customers c
GROUP BY "productVendor";
